input.sparql:
SELECT ?point ?series ?point_label WHERE {
  ?zone brick:hasSubsection ?point .
  FILTER(str(?zone) = "Perimeter_ZN_2" || str(?zone) = "Perimeter_ZN_3")
  ?point brick:hasTimeseriesId ?series .
}

SELECT ?z ?pname WHERE {
  ?z a brick:Zone .
  FILTER(str(?z) LIKE "%Perimeter_ZN%")
}

